void testConnectionClose() throws Exception {
    final OutputStream outStream = Mockito.mock(OutputStream.class);
    Mockito.when(socket.getOutputStream()).thenReturn(outStream);
    conn.bind(socket);
    conn.ensureOpen();
    conn.outbuffer.write(0, outStream);
    Assertions.assertTrue(conn.isOpen());
    conn.close();
    Assertions.assertFalse(conn.isOpen());
    Mockito.verify(outStream, Mockito.times(1)).write(ArgumentMatchers.any(), ArgumentMatchers.anyInt(), ArgumentMatchers.anyInt());
    Mockito.verify(socket, Mockito.times(1)).close();
    conn.close();
    Mockito.verify(socket, Mockito.times(1)).close();
    Mockito.verify(outStream, Mockito.times(1)).write(ArgumentMatchers.any(), ArgumentMatchers.anyInt(), ArgumentMatchers.anyInt());
}

