@Test
void testInputOneFrame() throws Exception {
    final WritableByteChannelMock writableChannel = new WritableByteChannelMock(1024);
    final FrameOutputBuffer outbuffer = new FrameOutputBuffer(16 * 1024);
    final byte[] data = new byte[FrameConsts.MIN_FRAME_SIZE];
    for (int i = 0; i < FrameConsts.MIN_FRAME_SIZE; i++) {
        data[i] = (byte) (i % 16);
    }
    final RawFrame frame = new RawFrame(FrameType.DATA.getValue(), 0, 1, ByteBuffer.wrap(data));
    outbuffer.write(frame, writableChannel);
    final byte[] bytes = writableChannel.toByteArray();
    final AbstractH2StreamMultiplexer streamMultiplexer = new H2StreamMultiplexerImpl(protocolIOSession, FRAME_FACTORY, StreamIdGenerator.ODD, httpProcessor, CharCodingConfig.DEFAULT, H2Config.custom().setMaxFrameSize(FrameConsts.MIN_FRAME_SIZE).build(), h2StreamListener, () -> streamHandler);
    Assertions.assertThrows(H2ConnectionException.class, () -> streamMultiplexer.onInput(ByteBuffer.wrap(bytes)));
    Mockito.verify(h2StreamListener).onFrameInput(ArgumentMatchers.same(streamMultiplexer), ArgumentMatchers.eq(1), ArgumentMatchers.any());
    Assertions.assertThrows(H2ConnectionException.class, () -> {
        int pos = 0;
        int remaining = bytes.length;
        while (remaining > 0) {
            final int chunk = Math.min(2048, remaining);
            streamMultiplexer.onInput(ByteBuffer.wrap(bytes, pos, chunk));
            pos += chunk;
            remaining -= chunk;
        }
        Mockito.verify(h2StreamListener).onFrameInput(ArgumentMatchers.same(streamMultiplexer), ArgumentMatchers.eq(1), ArgumentMatchers.any());
    });
}

